'use strict';
function emptyBankHTML(){return L`<section class="import-welcome"><span class="import-mark">＋</span><div><h2>你的题库，从这里开始。</h2><p>平台不附带第三方题目。导入 PDF 或 JSON 题库，也可以直接粘贴文字创建练习。</p><div class="import-buttons"><button class="btn" data-action="questions">导入我的题目 →</button><button class="btn secondary" data-action="demo">试用原创示例</button></div>${window.BANK_LOAD_ERROR?`<p class="ai-error">${esc(window.BANK_LOAD_ERROR)}</p>`:''}</div></section>`}
function importerPage(){return L`<div class="hello">BRING YOUR OWN QUESTIONS</div><div class="headline"><div><h1>你的材料，你的练习空间。</h1><p>上传 PDF、导入 JSON 或填写文字，整理成可计时的练习。</p></div><button class="btn secondary" id="back-library">返回题库 →</button></div><div class="import-steps"><span>01　准备题目</span><span>02　检查预览</span><span>03　开始练习</span></div><div class="import-columns"><div>${pdfImportHTML()}<section class="settings-card"><h3>导入 JSON 题库</h3><p>已有结构化题目可直接导入 JSON（最多 2 MB / 500 组）。</p><label class="upload-zone" for="question-file"><b>＋ 选择 JSON 文件</b><span>文件仅在当前浏览器解析</span></label><input id="question-file" type="file" accept=".json,application/json" hidden><div class="import-buttons"><button class="btn secondary" id="download-template">下载 JSON 模板</button><button class="btn secondary" id="try-demo">加载原创示例</button></div><p>模板内的 7 组题均为本项目新编演示内容，用于展示数据格式，并非官方试题。</p><div id="import-preview" aria-live="polite"></div></section></div><section class="settings-card"><h3>直接填写题目</h3><form id="question-form"><label>题型<select id="question-kind">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label><label>标题<input id="question-title" maxlength="160" required placeholder="例如：给图书馆写一封建议邮件"></label><label>时限（秒；口语为每小题）<input id="question-seconds" type="number" min="10" max="7200" value="180" required></label><div id="question-fields"></div><button class="btn" type="submit">检查并预览 →</button><p class="form-error" id="form-error" role="alert"></p></form></section></div><section class="settings-card"><h3>管理本地题库 <small>共 ${BANK.length} 组</small></h3><p>题目、作答和录音不会自动上传到公共题库。分享导出文件前，请确认你有权分发其中的材料。</p><div class="import-buttons"><button class="btn secondary" id="export-questions" ${BANK.length?'':'disabled'}>导出题目 JSON</button><button class="btn secondary" data-action="backup">导出完整备份</button><button class="btn danger-button" id="delete-questions" ${BANK.length||data.history.length?'':'disabled'}>清空题库与记录</button></div><p>手动点击写作 AI 批改时，仅所选题目和该篇作文会通过本机 Codex 发给模型；其他题目不会一并发送。</p></section>`}
function questionFields(){let k=$('#question-kind').value;$('#question-seconds').value={fill:180,daily:300,academic:600,email:420,discussion:600,repeat:20,interview:45}[k];let area=(id,label,placeholder)=>`<label>${label}<textarea id="${id}" rows="5" placeholder="${placeholder}" required></textarea></label>`;
 $('#question-fields').innerHTML=['email','discussion'].includes(k)?area('q-prompt',tr('题目要求（包含所有要点及讨论材料）'),tr('粘贴或填写完整题目要求…'))+(k==='email'?tr('<label>收件人（选填）<input id="q-to" maxlength="300"></label><label>邮件主题（选填）<input id="q-subject" maxlength="500"></label>'):''):k==='fill'?area('q-passage',tr('填词段落（词首＋下划线）'),tr('例如：We ma__ a plan. Each underscore represents one missing letter.'))+tr('<label>完整单词答案（选填；按顺序用英文逗号分隔）<input id="q-answers" placeholder="例如：make"></label>'):['daily','academic'].includes(k)?area('q-passage',tr('阅读材料'),tr('粘贴阅读文章或通知…'))+area('q-stem',tr('问题'),tr('填写一个选择题…'))+'<div class="option-fields">'+['A','B','C','D'].map(l=>`<label>${l}<input id="q-option-${l}" required maxlength="3000"></label>`).join('')+tr('</div><label>参考答案<select id="q-answer"><option value="">暂不填写</option>')+['A','B','C','D'].map(l=>`<option>${l}</option>`).join('')+tr('</select></label><p>表单每组创建一道阅读题；同一篇文章下的多道题请使用 JSON 模板。</p>'):area('q-speaking',tr('口语句子或问题（每行一题）'),tr('每一行填写一句复述内容或一个面试问题。'));
}
function formQuestion(){let k=$('#question-kind').value,q={id:'custom-'+crypto.randomUUID(),kind:k,title:$('#question-title').value,seconds:Number($('#question-seconds').value)};if(['email','discussion'].includes(k)){q.prompt=$('#q-prompt').value;q.to=$('#q-to')?.value||'';q.subject=$('#q-subject')?.value||''}else if(k==='fill'){q.passage=$('#q-passage').value;q.answers=$('#q-answers').value.trim()?$('#q-answers').value.split(',').map(s=>s.trim()):[]}else if(['daily','academic'].includes(k)){q.passage=$('#q-passage').value;q.questions=[{stem:$('#q-stem').value,options:['A','B','C','D'].map(l=>({label:l,text:$('#q-option-'+l).value})),answer:$('#q-answer').value||null}]}else q.questions=$('#q-speaking').value.split('\n').map(s=>s.trim()).filter(Boolean).map(stem=>({stem}));return q}
function commitBankAndProgress(questions,next){let oldQuestions=localStorage.getItem(PracticeBank.key),oldData=localStorage.getItem(KEY);try{PracticeBank.store(questions);localStorage.setItem(KEY,JSON.stringify(next))}catch(e){if(oldQuestions===null)localStorage.removeItem(PracticeBank.key);else localStorage.setItem(PracticeBank.key,oldQuestions);if(oldData===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,oldData);throw e}}
function previewQuestions(input){const qs=PracticeBank.validate(input);if(!qs.length)throw Error(tr('文件中没有题目'));const duplicates=qs.filter(q=>BANKMAP[q.id]);if(duplicates.length)throw Error(tr('已有相同 id：')+duplicates.map(q=>q.id).join('、')+tr('。请修改 id，避免覆盖旧作答。'));if(qs.length+BANK.length>500)throw Error(tr('题库总量最多 500 组'));
 modal(L`<h2>确认导入 ${qs.length} 组题目</h2><p>新题会加入当前题库，不覆盖已有记录。请核对题型、内容和答案。</p><div class="import-list">${qs.map(q=>`<details><summary><b>${esc(q.title)}</b> · ${TYPES[q.kind].name}</summary><pre>${esc(q.prompt||q.passage||'')}</pre>${q.questions?.map(x=>`<div><p>${esc(x.stem)}</p>${x.options?.map(o=>`<p>${o.label}. ${esc(o.text)}</p>`).join('')||''}${['daily','academic'].includes(q.kind)?L`<p>参考答案：${esc(x.answer||tr('未填写'))}</p>`:''}</div>`).join('')||''}${q.kind==='fill'?L`<p>完整单词答案：${q.answers.map(a=>esc(a||tr('未填写'))).join(' / ')}</p>`:''}</details>`).join('')}</div><label class="rights-check"><input type="checkbox" id="preview-rights"> 我有权使用这些材料，并已核对预览。</label><p id="import-error" role="alert" class="form-error"></p><div class="modal-actions"><button class="btn secondary" id="cancel-questions">取消</button><button class="btn" id="confirm-questions" disabled>加入我的题库</button></div>`);$('#preview-rights').onchange=e=>$('#confirm-questions').disabled=!e.target.checked;$('#cancel-questions').onclick=closeModal;$('#confirm-questions').onclick=()=>{try{PracticeBank.store([...BANK,...qs]);location.reload()}catch(e){$('#import-error').textContent=tr('未能保存：')+e.message+tr('。请先导出备份，释放浏览器空间。')}};
}
async function loadDemo(){try{let r=await fetch('templates/example-questions'+(I18N.lang()==='en'?'.en':'')+'.json');if(!r.ok)throw Error(tr('无法读取示例'));previewQuestions(await r.json())}catch(e){toast(e.message)}}
function bindImporter(){
 bindPDFImporter();
 $('#back-library').onclick=()=>go('library');$('#question-kind').onchange=questionFields;questionFields();$('#question-form').onsubmit=e=>{e.preventDefault();try{previewQuestions([formQuestion()]);$('#form-error').textContent=''}catch(error){$('#form-error').textContent=error.message}};
 $('#question-file').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error(tr('JSON 文件最多支持 2 MB'));previewQuestions(JSON.parse(await file.text()))}catch(error){$('#import-preview').textContent=tr('未导入：')+error.message}finally{e.target.value=''}};
 $('#try-demo').onclick=loadDemo;$('#download-template').onclick=async()=>{try{let r=await fetch('templates/example-questions'+(I18N.lang()==='en'?'.en':'')+'.json');if(!r.ok)throw Error();download(await r.text(),'practice-questions-template.json','application/json')}catch{toast(tr('模板读取失败'))}};
 $('#export-questions').onclick=()=>download(JSON.stringify({format:'practice-studio-questions',version:1,questions:BANK},null,2),'my-practice-questions.json','application/json');
 $('#delete-questions').onclick=()=>{modal(tr('<h2>清空本地题库与记录？</h2><p>将删除当前网址下的题目、作答、练习进度、收藏、报告副本和录音。不能撤销，请先导出完整备份。本机 AI 报告缓存需另行删除项目的 .local-data 文件夹。</p><div class="modal-actions"><button class="btn secondary" id="cancel-delete">取消</button><button class="btn danger-button" id="confirm-delete">确认清空</button></div>'));$('#cancel-delete').onclick=closeModal;$('#confirm-delete').onclick=async()=>{try{$('#confirm-delete').disabled=true;let d=await db();await new Promise((resolve,reject)=>{let tx=d.transaction('audio','readwrite');tx.objectStore('audio').clear();tx.oncomplete=()=>{d.close();resolve()};tx.onerror=()=>{d.close();reject(tx.error)}});commitBankAndProgress([],{history:[],favorites:[],attempts:{},session:null,mode:'timed',autoGradeWriting:false});location.reload()}catch(e){toast(tr('未能完成清空：')+e.message)}}};
}
